{
  "date": "2026-09-01",
  "rules_in_force": "P.L. 119-21 limits (periods of instruction beginning on or after July 1, 2026)",
  "dependent_undergraduate": {
    "annual_total": {
      "first_year": 5500,
      "second_year": 6500,
      "third_year_and_beyond": 7500
    },
    "annual_subsidized_max": {
      "first_year": 3500,
      "second_year": 4500,
      "third_year_and_beyond": 5500
    },
    "aggregate_total": 31000,
    "aggregate_subsidized_max": 23000,
    "note": "Excludes dependent students whose parents cannot get a Direct PLUS Loan; those students get the independent limits. Not changed by P.L. 119-21.",
    "less_than_full_time": "Annual limit reduced in direct proportion to less-than-full-time enrollment (rounded to the nearest whole percentage point), per a schedule the Secretary publishes."
  },
  "independent_undergraduate": {
    "annual_total": {
      "first_year": 9500,
      "second_year": 10500,
      "third_year_and_beyond": 12500
    },
    "annual_subsidized_max": {
      "first_year": 3500,
      "second_year": 4500,
      "third_year_and_beyond": 5500
    },
    "aggregate_total": 57500,
    "aggregate_subsidized_max": 23000,
    "note": "Also applies to dependent undergraduates whose parents cannot get a Direct PLUS Loan. Not changed by P.L. 119-21.",
    "less_than_full_time": "Annual limit reduced in direct proportion to less-than-full-time enrollment, per the Secretary's schedule."
  },
  "graduate": {
    "unsubsidized_annual": 20500,
    "unsubsidized_aggregate_in_addition_to_undergraduate": 100000,
    "grad_plus": "Not available. Graduate PLUS ended for periods of instruction beginning on or after July 1, 2026 (interim exception below).",
    "aggregate_note": "If the student is or has been a professional student, the graduate aggregate is $200,000 minus what was borrowed for professional study.",
    "definition": "Graduate student: program that awards a graduate credential other than a professional degree."
  },
  "professional": {
    "unsubsidized_annual": 50000,
    "unsubsidized_aggregate_in_addition_to_undergraduate": 200000,
    "grad_plus": "Not available from July 1, 2026 (interim exception below).",
    "aggregate_note": "If the student is or has been a graduate (non-professional) student, the professional aggregate is $200,000 minus what was borrowed for graduate study.",
    "definition": "Professional student: program that awards a professional degree as defined in 34 CFR 668.2 as in effect on July 4, 2025."
  },
  "parent_plus": {
    "annual_per_dependent_student_all_parents": 20000,
    "aggregate_per_dependent_student_all_parents": 65000,
    "aggregate_note": "Counted without regard to amounts repaid, forgiven or discharged.",
    "less_than_full_time": "Per FSA's FAQ, Parent PLUS is not reduced for less-than-full-time enrollment.",
    "repayment": "Parent PLUS loans made on or after July 1, 2026 can be repaid only under the Tiered Standard plan; they cannot use RAP."
  },
  "lifetime_limit_all_student_loans": {
    "amount": 257500,
    "note": "Lifetime maximum for loans a student borrows under Title IV (undergraduate, graduate and professional, Direct and FFEL), not counting Parent PLUS loans borrowed for a dependent. Counted without regard to amounts repaid, forgiven or discharged."
  },
  "institution_may_set_lower_limits": "From July 1, 2026 a school may set lower annual loan limits for a program, applied the same way to all students in that program.",
  "interim_exception": "A student who on June 30, 2026 was enrolled in a program and had received a Direct Loan for it (or whose parent had) keeps the old limits, including Grad PLUS and uncapped Parent PLUS, for the expected time to credential: the lesser of 3 academic years or the time left in the program.",
  "regulation_note": "Loan limits come straight from HEA sec. 455(a)(3)-(8) as amended by P.L. 119-21 sec. 81001. The proration schedule for less-than-full-time study and the professional-degree list are set by the Department; check your school's financial aid office.",
  "summary": "Federal loan limits for a period starting 2026-09-01 (P.L. 119-21 limits (periods of instruction beginning on or after July 1, 2026)): graduate unsubsidized $20,500.00 a year; professional unsubsidized $50,000.00 a year; Parent PLUS $20,000.00 a year and $65,000.00 total per student; dependent undergraduate $5,500.00/$6,500.00/$7,500.00 by year; independent undergraduate $9,500.00/$10,500.00/$12,500.00 by year; lifetime cap $257,500.00 (excluding Parent PLUS). Students enrolled with a loan on June 30, 2026 keep the old limits for up to 3 academic years.",
  "as_of": "2026-11-02",
  "source": "https://www.govinfo.gov/content/pkg/PLAW-119publ21/html/PLAW-119publ21.htm",
  "more": "https://www.mcpstamp.com/free-servers/?utm_source=mcp&utm_medium=student-loan-repayment-assistance-plan-calculator-mcp",
  "disclaimer": "General information, not financial or legal advice. Your servicer computes the official payment from your certified income and loan records. Use the StudentAid.gov Loan Simulator to confirm."
}
